// Pure domain: validation and rules. No I/O.

export const MAX_TITLE = 200;
export const MAX_BODY = 100_000;
export const MAX_REQUEST_BYTES = 2 * 1024 * 1024;

export interface FieldError { field: string; message: string }
export type Parsed<T> = { ok: true; value: T } | { ok: false; errors: FieldError[] };

// Unicode White_Space (not U+200B, not U+FEFF; JS trim() would strip FEFF but miss NEL).
const WS = "[\\t-\\r \\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]";
const TRIM_RE = new RegExp(`^${WS}+|${WS}+$`, "gu");
export const trimWs = (s: string): string => s.replace(TRIM_RE, "");

export const cpLength = (s: string): number => [...s].length;

const READ_ONLY = ["id", "teamId", "authorId", "version", "createdAt", "updatedAt", "deletedAt"];
const WRITABLE = ["title", "body"];

function validate(
  input: unknown,
  requireTitle: boolean,
): Parsed<{ title?: string; body?: string }> {
  if (input === null || typeof input !== "object" || Array.isArray(input)) {
    return { ok: false, errors: [{ field: "$", message: "must be a JSON object" }] };
  }
  const obj = input as Record<string, unknown>;
  const errors: FieldError[] = [];
  for (const k of Object.keys(obj)) {
    if (READ_ONLY.includes(k)) errors.push({ field: k, message: "is read-only" });
    else if (!WRITABLE.includes(k)) errors.push({ field: k, message: "unknown field" });
  }
  const out: { title?: string; body?: string } = {};
  if ("title" in obj) {
    if (typeof obj.title !== "string") errors.push({ field: "title", message: "must be a string" });
    else {
      const t = trimWs(obj.title);
      const n = cpLength(t);
      if (n < 1 || n > MAX_TITLE) errors.push({ field: "title", message: `must be 1-${MAX_TITLE} characters after trimming` });
      else out.title = t;
    }
  } else if (requireTitle) errors.push({ field: "title", message: "is required" });
  if ("body" in obj) {
    if (typeof obj.body !== "string") errors.push({ field: "body", message: "must be a string" });
    else if (cpLength(obj.body) > MAX_BODY) errors.push({ field: "body", message: `must be at most ${MAX_BODY} characters` });
    else out.body = obj.body;
  }
  if (!requireTitle && errors.length === 0 && Object.keys(obj).length === 0) {
    errors.push({ field: "$", message: "must contain at least one field" });
  }
  return errors.length ? { ok: false, errors } : { ok: true, value: out };
}

export const parseCreate = (input: unknown): Parsed<{ title: string; body: string }> => {
  const r = validate(input, true);
  if (!r.ok) return r;
  return { ok: true, value: { title: r.value.title!, body: r.value.body ?? "" } };
};

export const parsePatch = (input: unknown) => validate(input, false);

export const etagFor = (version: number): string => `"${version}"`;

export type Precondition =
  | { kind: "missing" }
  | { kind: "version"; matches: (v: number) => boolean };

/** Interpret an If-Match header. Missing or `*` -> "missing" (428). */
export function parseIfMatch(header: string | null): Precondition {
  if (header === null) return { kind: "missing" };
  const h = header.trim();
  if (h === "" || h === "*") return { kind: "missing" };
  const tags = h.split(",").map((s) => s.trim());
  if (tags.includes("*")) return { kind: "missing" };
  // RFC 9110 strong comparison on the opaque string: weak tags never equal.
  return { kind: "version", matches: (v) => tags.includes(etagFor(v)) };
}

export const isJsonContentType = (ct: string | null): boolean =>
  (ct ?? "").split(";")[0].trim().toLowerCase() === "application/json";

export const isoNow = (): string => new Date().toISOString();

/** `?archived=`: only exact "true" / "false"; null when absent means false. */
export function parseArchived(raw: string | null): Parsed<boolean> {
  if (raw === null || raw === "false") return { ok: true, value: false };
  if (raw === "true") return { ok: true, value: true };
  return { ok: false, errors: [{ field: "archived", message: "must be true or false" }] };
}
import { DatabaseSync } from "node:sqlite";
import { createHash } from "node:crypto";

export interface Note {
  id: string; teamId: string; authorId: string; title: string; body: string;
  version: number; createdAt: string; updatedAt: string; deletedAt?: string;
}
export interface TeamRole { id: string; name: string; role: "owner" | "member" }
export interface User { id: string; name: string }

type Row = Record<string, string | number | null>;
const toNote = (r: Row): Note => {
  const n: Note = {
    id: r.id as string, teamId: r.team_id as string, authorId: r.author_id as string,
    title: r.title as string, body: r.body as string, version: r.version as number,
    createdAt: r.created_at as string, updatedAt: r.updated_at as string,
  };
  if (r.deleted_at !== null) n.deletedAt = r.deleted_at as string;
  return n;
};

export class Store {
  private db: DatabaseSync;
  constructor(path: string, schemaSql: string) {
    this.db = new DatabaseSync(path);
    this.db.exec(schemaSql);
  }

  userByToken(token: string): User | null {
    const hash = createHash("sha256").update(token).digest("hex");
    const r = this.db.prepare("SELECT id, name FROM users WHERE token_hash = ?").get(hash) as Row | undefined;
    return r ? { id: r.id as string, name: r.name as string } : null;
  }

  teamsOf(userId: string): TeamRole[] {
    return (this.db.prepare(
      `SELECT t.id, t.name, m.role FROM memberships m JOIN teams t ON t.id = m.team_id
       WHERE m.user_id = ? ORDER BY t.id`).all(userId) as Row[])
      .map((r) => ({ id: r.id as string, name: r.name as string, role: r.role as "owner" | "member" }));
  }

  isMember(teamId: string, userId: string): boolean {
    return !!this.db.prepare("SELECT 1 FROM memberships WHERE team_id = ? AND user_id = ?").get(teamId, userId);
  }

  listNotes(teamId: string, archived: boolean): Note[] {
    const cond = archived ? "deleted_at IS NOT NULL" : "deleted_at IS NULL";
    return (this.db.prepare(`SELECT * FROM notes WHERE team_id = ? AND ${cond} ORDER BY seq DESC`).all(teamId) as Row[]).map(toNote);
  }

  /** Note by id regardless of deletion state. */
  findNote(id: string): Note | null {
    const r = this.db.prepare("SELECT * FROM notes WHERE id = ?").get(id) as Row | undefined;
    return r ? toNote(r) : null;
  }

  createNote(teamId: string, authorId: string, title: string, body: string, now: string): Note {
    const id = crypto.randomUUID();
    this.db.prepare(
      `INSERT INTO notes (id, team_id, author_id, title, body, version, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 1, ?, ?)`).run(id, teamId, authorId, title, body, now, now);
    return this.findNote(id)!;
  }

  /** Compare-and-set update of a live note. Returns null if the version no longer matches. */
  updateNote(id: string, expected: number, fields: { title?: string; body?: string }, now: string): Note | null {
    const r = this.db.prepare(
      `UPDATE notes SET title = COALESCE(?, title), body = COALESCE(?, body),
         version = version + 1, updated_at = ?
       WHERE id = ? AND version = ? AND deleted_at IS NULL`)
      .run(fields.title ?? null, fields.body ?? null, now, id, expected);
    return r.changes === 1 ? this.findNote(id) : null;
  }

  /** Idempotent soft delete: keeps the original deletedAt if already deleted. */
  softDelete(id: string, now: string): void {
    this.db.prepare("UPDATE notes SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL").run(now, id);
  }

  /** Restores a deleted note (version+1); a live note is returned untouched. */
  restore(id: string, now: string): Note | null {
    this.db.prepare(
      `UPDATE notes SET deleted_at = NULL, version = version + 1, updated_at = ?
       WHERE id = ? AND deleted_at IS NOT NULL`).run(now, id);
    return this.findNote(id);
  }
}
import {
  etagFor, isJsonContentType, isoNow, MAX_REQUEST_BYTES, parseArchived, parseCreate, parseIfMatch, parsePatch,
  type FieldError,
} from "./domain.ts";
import type { Note, Store, User } from "./store.ts";

const PROBLEM = "application/problem+json";

function problem(status: number, title: string, extra: Record<string, unknown> = {}, headers: HeadersInit = {}): Response {
  return new Response(
    JSON.stringify({ type: `https://teamnotes.example/problems/${status}`, title, status, ...extra }),
    { status, headers: { "content-type": PROBLEM, ...headers } },
  );
}
// One fixed body: hidden, missing, malformed and unknown routes are byte-identical.
const notFound = () => problem(404, "Not Found");
const json = (status: number, body: unknown, headers: HeadersInit = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", ...headers } });
const noteResponse = (status: number, n: Note, headers: HeadersInit = {}) =>
  json(status, n, { etag: etagFor(n.version), ...headers });

type Body = { ok: true; value: unknown } | { ok: false; res: Response };
type Raw = { ok: true; bytes: Uint8Array } | { ok: false; res: Response };

/** Reads the raw body: non-empty non-JSON -> 415, then oversize -> 413. */
async function readRaw(req: Request): Promise<Raw> {
  const tooLarge = () => ({
    ok: false as const,
    res: problem(413, "Payload Too Large", {}, { connection: "close" }),
  });
  const nonJson = !isJsonContentType(req.headers.get("content-type"));
  const len = req.headers.get("content-length");
  if (len !== null && Number(len) > MAX_REQUEST_BYTES) {
    return nonJson ? { ok: false, res: problem(415, "Unsupported Media Type") } : tooLarge();
  }
  const buf = new Uint8Array(MAX_REQUEST_BYTES);
  let total = 0;
  if (req.body) {
    const reader = req.body.getReader();
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (total + value.byteLength > MAX_REQUEST_BYTES) { reader.cancel().catch(() => {}); return tooLarge(); }
      buf.set(value, total);
      total += value.byteLength;
    }
  }
  if (total > 0 && nonJson) return { ok: false, res: problem(415, "Unsupported Media Type") };
  return { ok: true, bytes: buf.subarray(0, total) };
}

/** For operations that require a JSON body: empty -> 400, malformed -> 400. */
async function readJson(req: Request): Promise<Body> {
  const raw = await readRaw(req);
  if (!raw.ok) return raw;
  if (raw.bytes.length === 0) return { ok: false, res: problem(400, "Request body required") };
  try {
    return { ok: true, value: JSON.parse(new TextDecoder().decode(raw.bytes)) };
  } catch {
    return { ok: false, res: problem(400, "Malformed JSON") };
  }
}

/** For operations that ignore the body (restore, DELETE): only media/size rules apply. */
async function checkIgnoredBody(req: Request): Promise<Response | null> {
  const raw = await readRaw(req);
