  const ok = parseCreate({ title: "  hi  " });
  assert(ok.ok && ok.value.title === "hi" && ok.value.body === "");
  assert(parseCreate({ title: "😀".repeat(200) }).ok);
  assert(!parseCreate({ title: "😀".repeat(201) }).ok);
  assertEquals(cpLength("😀"), 1);
});

